#!/usr/bin/env python3
# -*- coding: utf-8 -*-
# patch_layout_alana.py -- novo layout (fundo por nicho, hook esquerda 1-2 linhas,
# CTA COMENTE QUERO). Mexe em agents/narrated_video_agent.py + integrations/
# telegram_repurpose_hunter.py. Backup + py_compile + idempotente + restaura se falhar.
# Rode na VPS:  cd ~/jarvis && .venv/bin/python patch_layout_alana.py
import base64, py_compile, shutil, sys, time
from pathlib import Path

RAIZ = Path(__file__).resolve().parent
MAPA = {'agents/narrated_video_agent.py': [('', ''), ('', ''), ('', '')], 'integrations/telegram_repurpose_hunter.py': [('', '')]}

def aplicar(vps_rel, pares_b64):
    alvo = RAIZ / vps_rel
    if not alvo.exists():
        print(f"  ❌ nao achei {alvo}"); return None
    txt = alvo.read_text(encoding="utf-8").replace("\r\n", "\n")
    pares = [(base64.b64decode(o).decode(), base64.b64decode(n).decode()) for o, n in pares_b64]
    if all(n in txt for _, n in pares):
        print(f"  ✅ {vps_rel}: JA APLICADO"); return "ok"
    novo = txt
    for old, new in pares:
        if new in novo:
            continue
        if old not in novo:
            print(f"  ❌ ABORTADO {vps_rel}: bloco nao encontrado (VPS divergente):")
            print("     " + old.strip().splitlines()[0][:90]); return None
        if novo.count(old) != 1:
            print(f"  ❌ ABORTADO {vps_rel}: bloco ambiguo (!=1x)"); return None
        novo = novo.replace(old, new)
    bak = alvo.with_suffix(alvo.suffix + ".bak_" + time.strftime("%Y%m%d_%H%M%S"))
    shutil.copy2(alvo, bak)
    alvo.write_text(novo, encoding="utf-8")
    try:
        py_compile.compile(str(alvo), doraise=True)
    except Exception as e:
        shutil.copy2(bak, alvo)
        print(f"  ❌ py_compile falhou em {vps_rel}, RESTAUREI: {e}"); return None
    print(f"  ✅ {vps_rel}: APLICADO (backup {bak.name})")
    return "ok"

def main():
    ok = True
    for vps_rel, pares in MAPA.items():
        if aplicar(vps_rel, pares) is None:
            ok = False
    if ok:
        print("\n🎨 Layout novo aplicado. Reinicie:  systemctl restart jarvis")
        print("   Ajustes finos (sem re-patch) via .env: HK_Y, HK_FONT, HK_MARGEM,")
        print("   VIDEO_Y, VIDEO_W_FRAC, CTA_Y, CTA_TEXTO.")
    return 0 if ok else 1

if __name__ == "__main__":
    sys.exit(main())
